    else:
        return b'\x00' * ((32 - len(data) % 32) % 32) + data

def encode_uint(val, bits):
    return val.to_bytes(32, 'big')

def encode_int(val, bits):
    if val < 0:
        val = (1 << 256) + val
    return val.to_bytes(32, 'big')

def encode_bool(val):
    return (1 if val else 0).to_bytes(32, 'big')

def encode_address(val):
    if val.startswith('0x'): val = val[2:]
    return bytes.fromhex(val).rjust(32, b'\x00')

def encode_fixed_bytes(val, n):
    if val.startswith('0x'): val = val[2:]
    data = bytes.fromhex(val)
    if len(data) > n: raise ValueError("Too long")
    return data.ljust(32, b'\x00')

def encode_bytes(val):
    if val.startswith('0x'): val = val[2:]
    data = bytes.fromhex(val)
    length = encode_uint(len(data), 256)
    return length + pad32(data, right=True)

def encode_string(val):
    data = val.encode('utf-8')
    length = encode_uint(len(data), 256)
    return length + pad32(data, right=True)

def parse_type(type_str):
    # Very basic type parser
    if type_str.endswith(']'):
        m = re.match(r'^(.*)\[(\d+)?\]$', type_str)
        if m:
            base_type = m.group(1)
            size = m.group(2)
            return {'kind': 'array', 'base': parse_type(base_type), 'size': int(size) if size else None}
    if type_str.startswith('('):
        # Tuple
        inner = type_str[1:-1]
        # This split is naive and won't handle nested tuples
        parts = []
        depth = 0
        current = ""
        for char in inner:
            if char == '(': depth += 1
            elif char == ')': depth -= 1
            if char == ',' and depth == 0:
                parts.append(current)
                current = ""
            else:
                current += char
        parts.append(current)
        return {'kind': 'tuple', 'elems': [parse_type(p.strip()) for p in parts]}
    return {'kind': 'base', 'name': type_str}

def main():
    if len(sys.argv) < 2:
        return
    cmd = sys.argv[1]
    if cmd == 'encode':
        subcmd = sys.argv[2]
        if subcmd == 'params':
            lenient = '-l' in sys.argv or '--lenient' in sys.argv
