def encode_address(val):
    if val.startswith('0x'): val = val[2:]
    return bytes.fromhex(val).rjust(32, b'\x00')

def encode_fixed_bytes(val, n):
    if val.startswith('0x'): val = val[2:]
    data = bytes.fromhex(val)
    return data.ljust(32, b'\x00')

def parse_type(type_str):
    type_str = type_str.strip()
    if type_str.endswith(']'):
        m = re.match(r'^(.*)\[(\d+)?\]$', type_str)
        if m:
            base_type = m.group(1)
            size = m.group(2)
            return {'kind': 'array', 'base': parse_type(base_type), 'size': int(size) if size else None, 'type_str': type_str}
    if type_str.startswith('('):
        inner = type_str[1:-1]
        parts = []
        depth = 0
        current = ""
        for char in inner:
            if char == '(': depth += 1
            elif char == ')': depth -= 1
            if char == ',' and depth == 0:
                parts.append(current)
                current = ""
            else:
                current += char
        if current: parts.append(current)
        return {'kind': 'tuple', 'elems': [parse_type(p) for p in parts], 'type_str': type_str}
    return {'kind': 'base', 'name': type_str, 'type_str': type_str}

def is_dynamic(t):
    if t['kind'] == 'base':
        return t['name'] in ('string', 'bytes')
    if t['kind'] == 'array':
        if t['size'] is None: return True
        return is_dynamic(t['base'])
    if t['kind'] == 'tuple':
        return any(is_dynamic(e) for e in t['elems'])
    return False

def parse_value(v, t, lenient=False):
    if t['kind'] == 'base':
        if t['name'] == 'bool':
            if lenient:
                if v.lower() in ('true', '1'): return True
                if v.lower() in ('false', '0'): return False
            else:
                if v == '1': return True
                if v == '0': return False
            raise ValueError("Invalid data")
        if t['name'].startswith('uint'):
            if not lenient and not v.startswith('0x') and len(v) != 64:
                # The original tool gave Hex parsing error if it's not even length
                if len(v) % 2 != 0: raise ValueError("Odd number of digits")
                raise ValueError("Invalid data")
            return to_int(v)
        if t['name'].startswith('int'):
            return to_int(v)
        if t['name'] == 'address':
            return v
        if t['name'] == 'string':
            return v
        if t['name'] == 'bytes':
            return v
        if t['name'].startswith('bytes'):
            return v
    if t['kind'] == 'array':
        # v should be "[val1,val2,...]"
        v = v.strip()
        if v.startswith('[') and v.endswith(']'):
            inner = v[1:-1]
            # Naive split for array elements
            parts = []
            depth = 0
            current = ""
            for char in inner:
                if char == '[' or char == '(': depth += 1
                elif char == ']' or char == ')': depth -= 1
                if char == ',' and depth == 0:
                    parts.append(current)
                    current = ""
                else:
                    current += char
            if current: parts.append(current)
            return [parse_value(p.strip(), t['base'], lenient) for p in parts]
    if t['kind'] == 'tuple':
        v = v.strip()
        if v.startswith('(') and v.endswith(')'):
            inner = v[1:-1]
            parts = []
            depth = 0
            current = ""
            for char in inner:
                if char == '(' or char == '[': depth += 1
                elif char == ')' or char == ']': depth -= 1
                if char == ',' and depth == 0:
                    parts.append(current)
                    current = ""
                else:
                    current += char
            if current: parts.append(current)
            return [parse_value(p.strip(), et, lenient) for p, et in zip(parts, t['elems'])]
    raise ValueError("Invalid data")

def encode_value(v, t):
    if t['kind'] == 'base':
        if t['name'] == 'bool': return encode_bool(v)
        if t['name'].startswith('uint'): return encode_uint(v)
        if t['name'].startswith('int'): return encode_int(v)
        if t['name'] == 'address': return encode_address(v)
        if t['name'] == 'string':
            data = v.encode('utf-8')
            return encode_uint(len(data)) + pad32(data, right=True)
        if t['name'] == 'bytes':
            if v.startswith('0x'): v = v[2:]
            data = bytes.fromhex(v)
            return encode_uint(len(data)) + pad32(data, right=True)
        if t['name'].startswith('bytes'):
            n = int(t['name'][5:])
            return encode_fixed_bytes(v, n)
    if t['kind'] == 'array':
        if t['size'] is None:
            # Dynamic array
            res = encode_uint(len(v))
            res += encode_params([t['base']] * len(v), v)
            return res
        else:
            # Fixed array
            return encode_params([t['base']] * t['size'], v)
    if t['kind'] == 'tuple':
        return encode_params(t['elems'], v)
    return b""

def encode_params(types, values):
    heads = []
    tails = []
    tail_offset = sum(32 for t in types)

    for t, v in zip(types, values):
        if is_dynamic(t):
            heads.append(encode_uint(tail_offset))
            tail_data = encode_value(v, t)
            tails.append(tail_data)
            tail_offset += len(tail_data)
        else:
            heads.append(encode_value(v, t))

    return b"".join(heads) + b"".join(tails)

def main():
    if len(sys.argv) < 2: return
    cmd = sys.argv[1]
    if cmd == 'encode':
        subcmd = sys.argv[2]
        if subcmd == 'params':
            lenient = '-l' in sys.argv or '--lenient' in sys.argv
            v_indices = [i for i, x in enumerate(sys.argv) if x == '-v']
            types = []
            values = []
            for idx in v_indices:
                types.append(parse_type(sys.argv[idx+1]))
                values.append(parse_value(sys.argv[idx+2], types[-1], lenient))
            print(encode_params(types, values).hex())
    elif cmd == 'decode':
        # To be implemented
        pass

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        # Match error style of original tool
        if "Odd number of digits" in str(e):
            print("Error: Hex parsing error: Odd number of digits\n\nCaused by:\n    Odd number of digits")
        elif "Invalid data" in str(e):
            print("Error: Invalid data")
        else:
            print(f"Error: {e}")
        sys.exit(1)
